INSERT INTO `ai_chatbot_conversations` (`id`, `session_id`, `user_id`, `resident_id`, `user_message`, `bot_response`, `intent_detected`, `confidence_score`, `appointment_booked`, `appointment_details`, `ip_address`, `user_agent`, `created_at`) VALUES
(1, 'sess_001', NULL, NULL, 'How do I report a theft?', 'I can help you file a blotter report for theft. Would you like to schedule an appointment with the barangay office?', 'blotter_inquiry', 0.98, 0, NULL, NULL, NULL, '2026-01-14 06:51:27'),
(2, 'sess_002', NULL, NULL, 'I need a barangay clearance for a job.', 'To get a barangay clearance, please bring a valid ID and proof of residency. You can also apply through our online portal.', 'certificate_inquiry', 0.95, 0, NULL, NULL, NULL, '2026-01-14 06:51:27'),
(3, 'sess_003', NULL, NULL, 'What are your office hours?', 'The barangay office is open Monday to Friday, 8:00 AM to 5:00 PM.', 'faq', 0.99, 0, NULL, NULL, NULL, '2026-01-14 06:51:27'),
(4, 'sess_004', NULL, NULL, 'Someone is playing loud music right now.', 'I understand. I can log a noise complaint for you or help you file a formal blotter report.', 'complaint', 0.92, 0, NULL, NULL, NULL, '2026-01-14 06:51:27'),
(5, 'sess_005', NULL, NULL, 'Can I schedule a meeting with the Captain?', 'Yes, I can help you book an appointment with the Barangay Captain. What is the purpose of your meeting?', 'appointment_request', 0.88, 0, NULL, NULL, NULL, '2026-01-14 06:51:27'),
(6, 'session_1768373826696_0', NULL, NULL, 'What is the barangay website?', 'Certificate fees vary by type. Please check with our office for current rates.', 'faq', 0.84, 0, NULL, NULL, NULL, '2025-10-20 17:57:20'),
(7, 'session_1768373826696_1', NULL, NULL, 'What are your office hours?', 'Certificate fees vary by type. Please check with our office for current rates.', 'faq', 0.68, 0, NULL, NULL, NULL, '2025-10-25 16:00:44'),
(8, 'session_1768373826696_2', NULL, NULL, 'How do I report a crime?', 'Blotter reports require complainant details and incident description.', 'blotter_inquiry', 0.97, 0, NULL, NULL, NULL, '2025-12-31 05:55:07'),
(9, 'session_1768373826696_3', NULL, NULL, 'What is the barangay office address?', 'Our barangay office provides various services including certificates, permits, and complaints.', 'general_inquiry', 0.74, 0, NULL, NULL, NULL, '2025-12-21 01:24:51'),
(10, 'session_1768373826696_4', NULL, NULL, 'How much do certificates cost?', 'We offer both online and in-person services for your convenience.', 'faq', 0.95, 0, NULL, NULL, NULL, '2025-12-28 10:07:49'),
(11, 'session_1768373826696_5', NULL, NULL, 'What services do you offer?', 'We offer certificate issuance, blotter filing, community programs, and resident services.', 'general_inquiry', 0.66, 0, NULL, NULL, NULL, '2025-12-23 12:19:23'),
(12, 'session_1768373826696_6', NULL, NULL, 'Can you help me with a business permit?', 'For certificates, please bring your cedula and barangay clearance fee.', 'certificate_inquiry', 0.90, 0, NULL, NULL, NULL, '2025-10-26 17:20:21'),
(13, 'session_1768373826696_7', NULL, NULL, 'What documents do I need for a certificate?', 'Certificate applications require ID verification and proper documentation.', 'certificate_inquiry', 0.77, 0, NULL, NULL, NULL, '2026-01-08 08:38:17'),
(14, 'session_1768373826696_8', NULL, NULL, 'What is the barangay website?', 'Office hours are Monday-Friday 8AM-5PM, Saturday 8AM-12NN.', 'faq', 0.80, 0, NULL, NULL, NULL, '2025-12-16 11:25:25'),
(15, 'session_1768373826696_9', NULL, NULL, 'Street lights are not working', 'We take community complaints seriously. Please provide specific details.', 'complaint', 0.83, 0, NULL, NULL, NULL, '2025-12-18 19:55:09'),
(16, 'session_1768373826696_10', NULL, NULL, 'How do I get a certificate of indigency?', 'For certificates, please bring your cedula and barangay clearance fee.', 'certificate_inquiry', 0.92, 0, NULL, NULL, NULL, '2025-10-20 10:51:35'),
(17, 'session_1768373826696_11', NULL, NULL, 'Do you have online services?', 'Office hours are Monday-Friday 8AM-5PM, Saturday 8AM-12NN.', 'faq', 0.84, 0, NULL, NULL, NULL, '2025-12-07 19:54:25'),
(18, 'session_1768373826696_12', NULL, NULL, 'Can you help me with a business permit?', 'I can help you with certificate requests. You\'ll need valid ID and proof of residency.', 'certificate_inquiry', 0.70, 0, NULL, NULL, NULL, '2025-10-30 05:34:14'),
(19, 'session_1768373826696_13', NULL, NULL, 'I want to schedule an appointment', 'Appointments are available Monday-Friday. What time works best for you?', 'appointment_request', 0.82, 0, NULL, NULL, NULL, '2025-12-21 06:59:03'),
(20, 'session_1768373826696_14', NULL, NULL, 'How much do certificates cost?', 'Office hours are Monday-Friday 8AM-5PM, Saturday 8AM-12NN.', 'faq', 0.96, 0, NULL, NULL, NULL, '2026-01-12 21:09:26'),
(21, 'session_1768373826696_15', NULL, NULL, 'What services do you offer?', 'Our barangay office provides various services including certificates, permits, and complaints.', 'general_inquiry', 0.89, 0, NULL, NULL, NULL, '2025-11-22 02:22:35'),
(22, 'session_1768373826696_16', NULL, NULL, 'What are your office hours?', 'Office hours are Monday-Friday 8AM-5PM, Saturday 8AM-12NN.', 'faq', 0.79, 0, NULL, NULL, NULL, '2025-11-30 12:53:18'),
(23, 'session_1768373826696_17', NULL, NULL, 'Street lights are not working', 'We appreciate residents reporting issues for community improvement.', 'complaint', 0.81, 0, NULL, NULL, NULL, '2025-12-15 23:18:22'),
(24, 'session_1768373826696_18', NULL, NULL, 'Someone stole my property, what should I do?', 'I can assist you with filing a blotter. Please provide incident details.', 'blotter_inquiry', 0.95, 0, NULL, NULL, NULL, '2025-11-12 20:52:29'),
